package br.com.arqueiros.manager;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebView; import android.webkit.WebViewClient; import android.webkit.WebSettings; import android.webkit.WebChromeClient; import android.webkit.CookieManager; import android.view.View; import android.widget.*;
public class MainActivity extends Activity { WebView web; @Override public void onCreate(Bundle b){super.onCreate(b); web=new WebView(this); setContentView(web); WebSettings s=web.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setAllowFileAccess(false); s.setAllowContentAccess(false); CookieManager.getInstance().setAcceptCookie(true); web.setWebViewClient(new WebViewClient()); web.setWebChromeClient(new WebChromeClient()); web.loadUrl("https://arqueiros-e-sports-manager.onrender.com"); } @Override public void onBackPressed(){ if(web!=null && web.canGoBack()) web.goBack(); else super.onBackPressed(); } }
